//! C-interface for the component.
//! This code must be unsafe.
//! Assumptions about correctness are introduced and need to be verified by other means.

use data::*;

#[cfg(test)]
use std::sync::Mutex;

#[cfg(not(test))]
extern "C" {
  fn get_crewRequests(value: *mut FlightStack::CrewRequests) -> bool;
  fn put_fdDisposition(value: *mut FlightStack::QualifiedFdAndSyncDisposition) -> bool;
  fn put_apDisposition(value: *mut FlightStack::QualifiedApDisposition) -> bool;
}

pub fn unsafe_get_crewRequests() -> FlightStack::CrewRequests
{
  unsafe {
    let value: *mut FlightStack::CrewRequests = &mut FlightStack::CrewRequests::default();
    get_crewRequests(value);
    return *value;
  }
}

pub fn unsafe_put_fdDisposition(value: &FlightStack::QualifiedFdAndSyncDisposition) -> bool
{
  unsafe {
    return put_fdDisposition(value as *const FlightStack::QualifiedFdAndSyncDisposition as *mut FlightStack::QualifiedFdAndSyncDisposition);
  }
}

pub fn unsafe_put_apDisposition(value: &FlightStack::QualifiedApDisposition) -> bool
{
  unsafe {
    return put_apDisposition(value as *const FlightStack::QualifiedApDisposition as *mut FlightStack::QualifiedApDisposition);
  }
}

//////////////////////////////////////////////////////////////////////////////////
// Testing Versions
//////////////////////////////////////////////////////////////////////////////////

#[cfg(test)]
lazy_static::lazy_static! {
  // simulate the global C variables that point to the microkit shared memory regions.  In a full
  // microkit system we would be able to mutate the shared memory for out ports since they're r/w,
  // but we couldn't do that for in ports since they are read-only
  pub static ref IN_crewRequests: Mutex<Option<FlightStack::CrewRequests>> = Mutex::new(None);
  pub static ref OUT_fdDisposition: Mutex<Option<FlightStack::QualifiedFdAndSyncDisposition>> = Mutex::new(None);
  pub static ref OUT_apDisposition: Mutex<Option<FlightStack::QualifiedApDisposition>> = Mutex::new(None);
}

#[cfg(test)]
pub fn initialize_test_globals() {
  unsafe {
    *IN_crewRequests.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_fdDisposition.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_apDisposition.lock().unwrap_or_else(|e| e.into_inner()) = None;
  }
}

#[cfg(test)]
pub fn get_crewRequests(value: *mut FlightStack::CrewRequests) -> bool
{
  unsafe {
    let guard = IN_crewRequests.lock().unwrap_or_else(|e| e.into_inner());
    *value = guard.expect("Not expecting None");
    true
  }
}

#[cfg(test)]
pub fn put_fdDisposition(value: *mut FlightStack::QualifiedFdAndSyncDisposition) -> bool
{
  unsafe {
    *OUT_fdDisposition.lock().unwrap_or_else(|e| e.into_inner()) = Some(*value);
    return true;
  }
}

#[cfg(test)]
pub fn put_apDisposition(value: *mut FlightStack::QualifiedApDisposition) -> bool
{
  unsafe {
    *OUT_apDisposition.lock().unwrap_or_else(|e| e.into_inner()) = Some(*value);
    return true;
  }
}
